head.script:
// ===== 리턴 값 출력 영역 (body_bottom.xml inline 복사) =====
// 리턴 값 초기화
scwin.btn_clear_onclick = function (e) {
    tbx_return.setValue("");
};

// 리턴 값 설정
scwin.setReturnValue = function (strValue) {
    tbx_return.setValue(tbx_return.getValue() + strValue);
    tbx_return.setValue(tbx_return.getValue() + "\n");
};



// ② 에서 명시할 진행 메시지
scwin.MSG = "업로드 진행 중";



// 진행 메시지 레이어 감시 결과
scwin.observer = null;
scwin.caseNo = "";
scwin.layerCreated = false;
scwin.layerMsg = "";



// 진행 메시지 레이어에 실제로 표시된 메시지를 읽는다.
//  · 메시지는 레이어 안 iframe 의 src 쿼리에 URLEncoder 로 실려 있으므로 URLDecoder 로 되돌린다.
scwin.readLayerMsg = function (objLayer) {
    try {
        var objFrame = objLayer.querySelector("iframe");
        if (objFrame !== null) {
            var strSrc = objFrame.getAttribute("src") || "";
            var nPos = strSrc.indexOf("?param=");
            if (nPos >= 0) return WebSquare.text.URLDecoder(strSrc.substring(nPos + 7));
        }

        if (WebSquare.layer && typeof WebSquare.layer.processMsg === "string") {
            return WebSquare.layer.processMsg;
        }
    } catch (e) {}

    return "";
};



// 진행 메시지 레이어는 업로드가 끝나면 제거되므로 등장 시점에 감시하여 메시지를 보관한다.
scwin.startWatch = function (strNo) {
    scwin.caseNo = strNo;
    scwin.layerCreated = false;
    scwin.layerMsg = "";

    if (scwin.observer !== null) scwin.observer.disconnect();

    scwin.observer = new MutationObserver(function () {
        try {
            if (scwin.layerCreated === true) return;

            var objLayer = document.getElementById("___processbar2_i");
            if (objLayer === null) return;

            scwin.layerCreated = true;
            scwin.layerMsg = scwin.readLayerMsg(objLayer);
        } catch (e) {}
    });

    scwin.observer.observe(document.body, {
        "childList" : true,
        "subtree" : true,
        "attributes" : true,
        "attributeFilter" : ["style"]
    });
};



// 이전 케이스에서 열린 Excel 파일 선택 레이어를 닫는다.
//  · 닫은 경우 true 를 반환한다. (닫기 처리가 끝나기 전에 다시 열면 ID 중복 경고가 발생하므로 호출부에서 간격을 둔다.)
scwin.closeOpened = function () {
    try {
        var objFrame = document.querySelector("[id$='_excelPop_wframe']");
        if (objFrame === null) return false;

        WebSquare.util.closePopup(objFrame.id.replace("_wframe", ""));
        return true;
    } catch (e) {}

    return false;
};



// processMsg 값만 달리하여 advancedExcelUpload 실행
//  · strMsg 가 undefined 이면 processMsg 를 아예 전달하지 않는다.
scwin.runCase = function (strNo, strMsg) {
    var bClosed = scwin.closeOpened();

    var fnRun = function () {
        scwin.startWatch(strNo);

        var objOptions = { "wframe" : true };
        if (strMsg !== undefined) objOptions.processMsg = strMsg;

        target1.advancedExcelUpload(objOptions);

        scwin.setReturnValue("[" + strNo + "] 설정한 processMsg : " + (strMsg === undefined ? "미설정 (기본값 \"upload...\")" : "\"" + strMsg + "\"") + " / 엔진에 전달된 processMsg : \"" + scwin.getPassedMsg() + "\"");
    };

    // 이전 레이어의 닫기 처리가 끝난 뒤 다음 케이스를 실행한다.
    if (bClosed === true) {
        setTimeout(fnRun, 800);
    } else {
        fnRun();
    }
};



// 엔진에 실제로 전달된 processMsg 값
//  · 업로드가 끝나면 비워지므로 advancedExcelUpload 호출 직후 바로 읽는다.
scwin.getPassedMsg = function () {
    try {
        var strInfo = target1._excelUploadInfo;
        if (strInfo === undefined || strInfo === null || strInfo === "") return "확인 불가";

        var strMsg = JSON.parse(strInfo).processMsg;
        if (strMsg === undefined || strMsg === null || strMsg === "") return "";

        return WebSquare.text.BASE64URLDecoder(strMsg);
    } catch (e) {}

    return "확인 불가";
};



// 업로드 완료 시점에 감시 결과를 출력한다.
scwin.target1_onfilereadend = function (value) {
    if (scwin.observer !== null) {
        scwin.observer.disconnect();
        scwin.observer = null;
    }

    if (scwin.layerCreated === true) {
        scwin.setReturnValue("[" + scwin.caseNo + "] 진행 메시지 레이어 생성 : 됨 / 표시된 메시지 : \"" + scwin.layerMsg + "\"");
    } else {
        scwin.setReturnValue("[" + scwin.caseNo + "] 진행 메시지 레이어 생성 : 안 됨");
    }

    scwin.setReturnValue("");
};



// ① processMsg 미설정
scwin.btn_case1_onclick = function () {
    scwin.runCase("①", undefined);
};

// ② processMsg 값 명시
scwin.btn_case2_onclick = function () {
    scwin.runCase("②", scwin.MSG);
};
